// Ambient light follows the hour: warm dawn, neutral day, amber dusk, cool night.
function daypart(){const h=new Date().getHours();document.documentElement.dataset.daypart=h<5||h>=20?'night':h<9?'dawn':h<16?'day':'dusk'}daypart();setInterval(daypart,600000);
const $=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
