let newsTab='latest',newsOpts={category:'',window:'24h'},newsStatus='';const newsCache=new Map();
const newsKey=()=>newsTab==='latest'?`latest|${newsOpts.category}|${newsOpts.window}`:newsTab;
async function loadNews(more=false){const k=newsKey(),entry=newsCache.get(k);if(newsStatus==='loading')return;newsStatus='loading';if(more)render();const q=new URLSearchParams({kind:newsTab});if(newsTab==='latest'){q.set('window',newsOpts.window);if(newsOpts.category)q.set('category',newsOpts.category);if(more&&entry?.data.page?.nextCursor)q.set('cursor',entry.data.page.nextCursor)}
 try{const data=await api('aihot?'+q);newsCache.set(k,more&&entry?{time:entry.time,data:{...data,items:[...entry.data.items,...(data.items||[])]}}:{time:Date.now(),data});newsStatus=''}catch(err){newsStatus=err.message||'读取失败'}if(view()==='news')render()}
let recordFilter=location.hash==='#life'?'personal':'all',recordQuery='',paperFilter='all',paperQuery='',settingsTab='appearance',editingPaper=null,editingProject=null;
let density=localStorage.getItem('wb-density')||'comfortable',reduceMotion=localStorage.getItem('wb-reduce-motion')==='true',theme=localStorage.getItem('wb-theme')||'system';
document.body.dataset.density=density;document.body.dataset.motion=reduceMotion?'reduced':'normal';
let token=sessionStorage.getItem('wb-access')||'',state=null,session=null,busy=false,loadingSession=false,model=localStorage.getItem('wb-model')||'deepseek-flash',effort=localStorage.getItem('wb-effort')||'low',editRecord=null,draft='',pendingImage=null,saveMood=true,streamText='',streamStatus='',loadingPhoto=false,sentAccepted=false;
let sessionLoadSerial=0,loadingSessionId=null,lastPageKey='',renderedMessages={id:null,count:0},liveShown=false,paletteItems=[],paletteIndex=0;
if(location.hash.startsWith('#access=')){token=location.hash.slice(8);sessionStorage.setItem('wb-access',token);history.replaceState(null,'',location.pathname+'#today')}
// Opening the app (a new tab, a home-screen icon, a restored phone tab) starts on 今天; only a manual refresh keeps the current page.
else if(performance.getEntriesByType('navigation')[0]?.type!=='reload'&&location.hash!=='#life')history.replaceState(null,'',location.pathname+'#today')
