const darkQuery=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(){if(theme==='system')delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=theme;const dark=theme==='dark'||(theme==='system'&&darkQuery.matches);$('meta[name="theme-color"]').content=dark?'#0e0f10':'#f7f6f3'}
applyTheme();darkQuery.addEventListener('change',applyTheme);
document.title=config.appName;$('#brandName').firstChild.textContent=config.appName;
for(const el of document.querySelectorAll('[data-icon]'))el.outerHTML=icon(el.dataset.icon);
