function positionPicker(){const d=$('#modelDialog'),anchor=$('#modelToggle');if(!d.open||!anchor)return;if(innerWidth<=760){d.style.removeProperty('left');d.style.removeProperty('top');return}const box=anchor.getBoundingClientRect();d.style.left=Math.max(12,Math.min(box.left,innerWidth-d.offsetWidth-16))+'px';d.style.top=Math.max(16,box.top-d.offsetHeight-12)+'px'}
