function openProject(p){if(!p)return;editingProject=p;$('#detailName').value=p.name;$('#detailStage').innerHTML=state.projectStages.map(x=>`<option>${e(x)}</option>`).join('');$('#detailStage').value=p.stage;for(const [field,key] of [['Question','question'],['Goal','goal'],['Progress','progress'],['Completed','completed'],['Next','nextAction']])$('#detail'+field).value=p[key]||'';$('#projectOrigin').textContent=(p.importSource?.sourceUpdatedAt?'原档案日期：'+new Date(p.importSource.sourceUpdatedAt).toLocaleDateString('zh-CN')+'。':'')+(p.userEditedAt?'最近更正：'+new Date(p.userEditedAt).toLocaleString('zh-CN')+'。':'可直接编辑下方内容。')+' 留空的内容表示尚未整理。';const linked=state.records.filter(r=>r.projectId===p.id&&r.scope==='research'),decisions=linked.map(parseDecision).filter(Boolean).sort((a,b)=>String(b.date).localeCompare(String(a.date))),rows=linked.filter(r=>!parseDecision(r));$('#projectLinkedRecords').innerHTML=decisionTimeline(decisions)+`<div class="linked-records"><h3>相关记录 <span>${rows.length}</span></h3>${rows.map(r=>`<details><summary>${e(r.text.split('\n')[0])}</summary><p>${e(r.text)}</p><button type="button" class="text-link" data-edit-project-record="${r.id}">${icon('edit')}修改这条记录</button></details>`).join('')||'<p class="fine">暂无关联记录。</p>'}</div>`;$('#projectDetailError').textContent='';$('#projectDetailDialog').showModal()}
