function renderPalette(q){q=q.trim().toLowerCase();const all=paletteSource();paletteItems=q?all.filter(x=>`${x.label} ${x.hint||''} ${x.group}`.toLowerCase().includes(q)).slice(0,30):all.filter(x=>x.group!=='研究项目'&&x.group!=='论文投稿').slice(0,15);paletteIndex=0;let group='';$('#paletteList').innerHTML=paletteItems.length?paletteItems.map((x,i)=>`${x.group!==group?`<div class="palette-group">${group=x.group}</div>`:''}<button type="button" class="palette-item" role="option" id="palette-${i}" data-palette-index="${i}" aria-selected="${i===0}">${icon(x.icon)}<span class="palette-label">${e(x.label)}</span>${x.hint?`<span class="palette-hint">${e(x.hint)}</span>`:''}${icon('enter','palette-enter')}</button>`).join(''):`<div class="palette-empty">${icon('search')}<span>没有找到“${e(q)}”</span></div>`;movePalette(0)}
function movePalette(i){if(!paletteItems.length)return;paletteIndex=(i+paletteItems.length)%paletteItems.length;for(const b of document.querySelectorAll('.palette-item'))b.setAttribute('aria-selected',String(Number(b.dataset.paletteIndex)===paletteIndex));const cur=$('#palette-'+paletteIndex);cur?.scrollIntoView({block:'nearest'});$('#paletteInput').setAttribute('aria-activedescendant','palette-'+paletteIndex)}
