document.addEventListener('input',ev=>{if(ev.target.id==='recordSearch'){recordQuery=ev.target.value;$('.notes-list').innerHTML=recordCards();loadPhotos()}if(ev.target.id==='paperSearch'){paperQuery=ev.target.value;$('#paperList').innerHTML=submissionList(state,paperFilter,paperQuery)}if(ev.target.id==='message'){draft=ev.target.value;grow(ev.target)}if(ev.target.id==='paletteInput')renderPalette(ev.target.value)});
