// Phone bottom sheets: drag the header down; past 110px or a quick flick dismisses, otherwise it springs back.
for(const d of document.querySelectorAll('.sheet-dialog')){const head=d.querySelector('.sheet-header');let y0=0,t0=0,dy=0,active=false;
 head.addEventListener('pointerdown',ev=>{if(innerWidth>760||ev.target.closest('button'))return;active=true;y0=ev.clientY;t0=performance.now();dy=0;head.setPointerCapture(ev.pointerId)});
 head.addEventListener('pointermove',ev=>{if(!active)return;dy=Math.max(0,ev.clientY-y0);d.style.transform=`translate3d(0,${dy}px,0)`});
 const end=()=>{if(!active)return;active=false;if(dy>110||(dy>30&&dy/(performance.now()-t0)>.6)){d.style.setProperty('--drag',dy+'px');d.style.transform='';closeDialog(d.id)}else if(dy){d.classList.add('settling');d.style.transform='';setTimeout(()=>d.classList.remove('settling'),360)}};
 head.addEventListener('pointerup',end);head.addEventListener('pointercancel',end);d.addEventListener('close',()=>{d.style.removeProperty('--drag');d.style.transform=''})}
